solution:
const http = require("http");

const PAGES = {
  "/": "Accueil",
  "/contact": "Écris à boutique@example.com",
};

const serveur = http.createServer((req, res) => {
  const texte = PAGES[req.url];
  res.writeHead(texte ? 200 : 404, { "Content-Type": "text/plain; charset=utf-8" });
  res.end(texte || "Page introuvable");
});
